link.script:
(function () {
  const TARGET_PATH = '/science/publications/';
  const GRID_SELECTOR = '.wp-grid-builder.wpgb-grid-2';
  const LINK_SELECTOR = GRID_SELECTOR + ' a[href]';

  function normalizePath(path) {
    return path.replace(/\/+$/, '') + '/';
  }

  function isTargetPage() {
    return normalizePath(window.location.pathname) === TARGET_PATH;
  }

  function getEventLink(event) {
    const origin = event.target instanceof Element
      ? event.target
      : event.target && event.target.parentElement;

    if (!origin || !origin.closest) {
      return null;
    }

    return origin.closest(LINK_SELECTOR);
  }

  function isProtectedLink(link) {
    const href = link.getAttribute('href') || '';
    const target = (link.getAttribute('target') || '').toLowerCase();
    const rel = (link.getAttribute('rel') || '').toLowerCase();

    return (
      target === '_blank' ||
      rel.includes('external') ||
      /\.pdf($|[?#])/i.test(href)
    );
  }

  function shouldIntercept(event, link) {
    if (!link) return false;
    if (event.defaultPrevented) return false;
    if (event.button !== 0) return false; // left click only
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return false;

    return isProtectedLink(link);
  }

  function openInNewTab(url) {
    const newWindow = window.open(url, '_blank', 'noopener,noreferrer');
    if (newWindow) {
      newWindow.opener = null;
    }
  }

  function handleClick(event) {
    if (!isTargetPage()) return;

    const link = getEventLink(event);
    if (!shouldIntercept(event, link)) return;

    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();

    openInNewTab(link.href);
  }

  window.addEventListener('click', handleClick, true);
})();

jQuery(document).ready(function ($) {

  var $container = $('.list-container');
  if (!$container.length) return;

  // Wrap desktop tabs in a .container
  var $tabsWrapper = $('
');
  var $tabs = $('');
  $tabsWrapper.append($tabs);

  var usedIds = {};
  var first = true;

  // Loop through each list item
  $container.find('.list-item').each(function () {

    var $item = $(this);

    // Wrap inner contents of list-item in a container
    if (!$item.find('.container').length) {
      $item.wrapInner('
');
    }

    // Wrap .container > img.list-item-img in .list-item-image-wrap (no double-wrap)
    (function wrapListItemImage() {
      var $innerContainer = $item.children('.container').first();
      if (!$innerContainer.length) return;

      // Prefer direct child image to avoid catching nested images in rich text
      var $img = $innerContainer.children('img.list-item-img').first();

      // Fallback if markup changes (still avoid wrapping images already wrapped)
      if (!$img.length) {
        $img = $innerContainer.find('> img.list-item-img').first();
      }

      if (!$img.length) return;

      // If already wrapped, do nothing
      if ($img.parent().hasClass('list-item-image-wrap')) return;

      $img.wrap('
');
    })();

    // Get heading text
    var headingText = $item.find('h2').first().text().trim();
    if (!headingText) return;

    // Generate unique slug ID
    var baseId = headingText
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');

    var id = baseId, n = 2;
    while (usedIds[id]) id = baseId + '-' + n++;
    usedIds[id] = true;

    $item.attr('id', id);

    // Insert mobile title button before each list-item
    var $mobileBtn = $('')
      .attr('data-target', id)
      .append(
        $('').text(headingText),
        $('')
      )
      .insertBefore($item);

    // Build desktop tab button
    var $tab = $('
');
    var $btn = $('')
      .attr('aria-controls', id)
      .attr('aria-selected', 'false')
      .data('target', id)
      .append(
        $('').text(headingText),
        $('')
      );

    $tab.append($btn);
    $tabs.append($tab);

    // First item active by default (desktop + initial content)
    if (first) {
      $tab.addClass('active');
      $btn.attr('aria-selected', 'true');

      $mobileBtn.addClass('active');

      $item.addClass('active').show();
      first = false;
    } else {
      $item.removeClass('active').hide();
    }

  });

  // Insert desktop tabs above list container
  $container.before($tabsWrapper);

  // Desktop tab click handler (fade swap)
  $tabs.on('click', '.list-tab-btn', function (e) {

    e.preventDefault();

    var targetId = $(this).data('target');
    var $newItem = $('#' + targetId);
    var $currentItem = $container.find('.list-item.active');

    if (!$newItem.length || $newItem.is($currentItem)) return;

    // Update active tab state
    $tabs.find('.list-tab').removeClass('active');
    $tabs.find('.list-tab-btn').attr('aria-selected', 'false');

    $(this).closest('.list-tab').addClass('active');
    $(this).attr('aria-selected', 'true');

    // Fade swap content
    $currentItem.stop(true, true).fadeOut(200, function () {
      $currentItem.removeClass('active');

      $newItem
        .stop(true, true)
        .addClass('active')
        .fadeIn(200);
    });

  });

  // Mobile button click handler (multi-open accordion)
  // NOTE: does NOT close others
  $(document).on('click', '.mobile-tab-title', function () {

    var $btn = $(this);
    var targetId = $btn.data('target');
    var $panel = $('#' + targetId);

    // Toggle active state
    $btn.toggleClass('active');

    // Toggle corresponding panel
    if ($btn.hasClass('active')) {
      $panel.addClass('active').stop(true, true).slideDown(200);
    } else {
      $panel.removeClass('active').stop(true, true).slideUp(200);
    }

  });

});

jQuery(document).ready(function ($) {
  $('.careers-gallery .gallery br').remove();
  function slickMobileOnly() {

    if ($(window).width() < 767) {

      if (!$('.careers-gallery .gallery').hasClass('slick-initialized')) {
        $('.careers-gallery .gallery').slick({
          slidesToShow: 1,
          slidesToScroll: 1,
          fade: true,
          arrows: true,
          dots: false,
          prevArrow: '',
          nextArrow: '',
          adaptiveHeight: false
        });
      }

    } else {

      if ($('.careers-gallery .gallery').hasClass('slick-initialized')) {
        $('.careers-gallery .gallery').slick('unslick');
      }

    }

  }

  // Run on page load
  slickMobileOnly();

  // Run again on resize
  $(window).on('resize', function () {
    slickMobileOnly();
  });

});

/**
 * Inject social links block immediately after:
 * footer.site-footer .footer-top .container-fluid .row .col .content a[data-v-273814c4]
 *
 * Safe for Vue DOM changes: retries until found, then injects once.
 */
(function ($) {
  'use strict';

  var TARGET_SELECTOR =
    'footer.site-footer .footer-top .container-fluid .row .col .content a[data-v-273814c4]';

  var INJECT_ID = 'js-injected-social-links';

  function buildMarkup() {
    return (
      '
' +
        '' +
          '
' +
            'LinkedIn' +
          '' +
          '
' +
            'Twitter' +
          '' +
        '' +
      ''
    );
  }

  function injectOnce() {
    // Prevent duplicates
    if (document.getElementById(INJECT_ID)) return true;

    var $target = $(TARGET_SELECTOR).first();
    if (!$target.length) return false;

    $target.after(buildMarkup());
    return true;
  }

  function startRetryInjection() {
    // Try immediately
    if (injectOnce()) return;

    // Retry for dynamic Vue hydration/re-renders
    var attempts = 0;
    var maxAttempts = 60; // ~30s at 500ms
    var interval = setInterval(function () {
      attempts++;
      if (injectOnce() || attempts >= maxAttempts) {
        clearInterval(interval);
      }
    }, 500);
  }

  $(startRetryInjection);

  // Optional: also listen for later DOM changes (Vue updates)
  // If you don't want ongoing observers, remove this block.
  var observer = new MutationObserver(function () {
    injectOnce();
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });

})(jQuery);


(function () {
  const SELECTOR_CONTAINER = "body.video-hero #hero-carousel .responsive-image";
  const SELECTOR_IMG = "img";

  const VIDEO_SRC_MP4 = "/wp-content/uploads/2026/07/olema-video-3.mp4";
  const VIDEO_POSTER = "/wp-content/uploads/2026/01/video-hero.jpg";
  const VIDEO_LOOP = true;
  const VIDEO_MUTED = true;
  const VIDEO_AUTOPLAY = true;
  const VIDEO_PLAYSINLINE = true;

  const WRAP_CLASS = "hero-video-wrap";
  const INJECT_FLAG = "videoInjected";

  // 0.5s polling (per your ask)
  const POLL_MS = 500;

  // Customize this to your site routing:
  // - If home is exactly "/" use that.
  // - If your SPA uses hash routing, include hash checks.
  function isHomeURL() {
    const path = (location.pathname || "").replace(/\/+$/, ""); // trim trailing slash
    const hash = location.hash || "";

    // Common cases: "/" OR "/home"
    if (path === "" || path === "/") return true;
    if (path === "/home") return true;

    // If Vue Router hash mode: "#/" or "#/home"
    if (hash === "#/" || hash === "#") return true;
    if (hash.startsWith("#/home")) return true;

    return false;
  }

  function containerExists() {
    return document.querySelector(SELECTOR_CONTAINER);
  }

  function injectInto(container) {
    if (!container) return;

    // If injected but wrap missing (DOM reshuffle), allow reinject.
    const existingWrap = container.querySelector(`:scope > .${WRAP_CLASS}`);
    if (container.dataset[INJECT_FLAG] === "1" && existingWrap) return;

    // Clean any partial remnants before injecting
    teardownContainer(container);

    const img = container.querySelector(SELECTOR_IMG);

    const cs = window.getComputedStyle(container);
    if (cs.position === "static") container.style.position = "relative";
    container.style.overflow = "hidden";

    const wrap = document.createElement("div");
    wrap.className = WRAP_CLASS;
    Object.assign(wrap.style, {
      position: "absolute",
      inset: "0",
      width: "100%",
      height: "100%",
      zIndex: "2",
      opacity: "0",
      transition: "opacity 250ms ease",
      pointerEvents: "none"
    });

    const video = document.createElement("video");
    video.className = "hero-video";

    // iOS/WebKit autoplay hardening: properties + attributes
    video.muted = true;
    video.defaultMuted = true;                 // important on iOS in some cases
    video.autoplay = true;
    video.loop = !!VIDEO_LOOP;
    video.playsInline = true;

    video.setAttribute("muted", "muted");
    video.setAttribute("autoplay", "autoplay");
    video.setAttribute("playsinline", "playsinline");
    video.setAttribute("webkit-playsinline", "webkit-playsinline");

    // Optional but recommended for true “background” behavior
    video.setAttribute("disablepictureinpicture", "disablepictureinpicture");
    video.disablePictureInPicture = true;

    // preload: iOS sometimes behaves better with metadata first; keep auto if you prefer
    video.preload = "metadata";

    const poster = VIDEO_POSTER || (img && img.currentSrc) || (img && img.src) || "";
    if (poster) video.poster = poster;

    const src = document.createElement("source");
    src.src = VIDEO_SRC_MP4;
    src.type = "video/mp4";
    video.appendChild(src);

    Object.assign(video.style, {
      width: "100%",
      height: "100%",
      objectFit: "cover",
      objectPosition: "center center",
      display: "block"
    });

    wrap.appendChild(video);
    container.appendChild(wrap);

    // Attempt play as soon as it’s in-DOM (iOS often wants this ordering)
    const tryPlay = () => {
      const p = video.play();
      if (p && typeof p.catch === "function") p.catch(() => {});
    };
    tryPlay();

    let revealed = false;
    const reveal = () => {
      if (revealed) return;
      revealed = true;
      wrap.style.opacity = "1";
    };

    const onReady = () => {
      reveal();
      tryPlay();
    };

    // iOS: loadedmetadata is a good early hook; keep canplay as well
    video.addEventListener("loadedmetadata", tryPlay, { once: true });
    video.addEventListener("canplay", onReady, { once: true });
    video.addEventListener("playing", reveal, { once: true });


    const kick = () => tryPlay();
    window.addEventListener("touchstart", kick, { once: true, passive: true });
    window.addEventListener("click", kick, { once: true, passive: true });


    // Fallback readyState polling (short-lived)
    const t0 = Date.now();
    const maxWait = 4000;
    const readyCheck = setInterval(() => {
      if (!document.documentElement.contains(video)) {
        clearInterval(readyCheck);
        return;
      }
      if (video.readyState >= 2) {
        clearInterval(readyCheck);
        onReady();
      } else if (Date.now() - t0 > maxWait) {
        clearInterval(readyCheck);
        // If it never becomes ready, keep image fallback (do nothing)
      }
    }, 100);

    container.dataset[INJECT_FLAG] = "1";
  }

  function teardownContainer(container) {
    if (!container) return;

    const wrap = container.querySelector(`:scope > .${WRAP_CLASS}`);
    if (wrap) {
      const video = wrap.querySelector("video");
      if (video) {
        try {
          video.pause();
          // free resources
          video.removeAttribute("src");
          while (video.firstChild) video.removeChild(video.firstChild);
          video.load();
        } catch (_) {}
      }
      wrap.remove();
    }

    if (container.dataset) delete container.dataset[INJECT_FLAG];
  }

  function teardownAll() {
    // remove wraps anywhere
    document.querySelectorAll(`.${WRAP_CLASS}`).forEach((wrap) => {
      const video = wrap.querySelector("video");
      if (video) {
        try {
          video.pause();
          video.removeAttribute("src");
          while (video.firstChild) video.removeChild(video.firstChild);
          video.load();
        } catch (_) {}
      }
      wrap.remove();
    });

    // clear flags if containers still exist
    document.querySelectorAll(SELECTOR_CONTAINER).forEach((c) => {
      if (c.dataset) delete c.dataset[INJECT_FLAG];
    });
  }

  // Optional but often required in “class bleed” situations:
  function normalizeBodyClassesForRoute() {
    if (!document.body) return;

    if (isHomeURL()) {
      // allow whatever your home page expects; do NOT force-add unless you must
      return;
    }

    // On non-home, forcibly remove classes that cause bleed
    document.body.classList.remove("home");
    document.body.classList.remove("video-hero");
  }

  // State machine
  let lastHref = "";
  let lastHome = null;

  function sync() {
    const href = location.href;
    const home = isHomeURL();

    const routeChanged = href !== lastHref;
    const homeChanged = home !== lastHome;

    // Always update trackers early
    lastHref = href;
    lastHome = home;

    if (routeChanged || homeChanged) {
      // Route transition boundary: normalize + enforce teardown if leaving home
      normalizeBodyClassesForRoute();
      if (!home) teardownAll();
    }

    if (!home) return;

    // Home: keep trying until container exists (fixes “start elsewhere → home”)
    const container = containerExists();
    if (container) injectInto(container);
  }

  // History API hooks (helps when polling interval misses fast transitions)
  (function installHistoryHooks() {
    const fire = () => window.dispatchEvent(new Event("locationchange"));
    const _pushState = history.pushState;
    history.pushState = function () {
      const ret = _pushState.apply(this, arguments);
      fire();
      return ret;
    };
    const _replaceState = history.replaceState;
    history.replaceState = function () {
      const ret = _replaceState.apply(this, arguments);
      fire();
      return ret;
    };
    window.addEventListener("popstate", fire);
    window.addEventListener("locationchange", sync);
  })();

  // MutationObserver: keep light; just call sync (route logic gates it)
  const mo = new MutationObserver(() => sync());
  mo.observe(document.documentElement, { childList: true, subtree: true });

  // URL polling: your requested 0.5s heartbeat
  setInterval(sync, POLL_MS);

  // initial
  sync();
})();




