jQuery(function ($) {
  const selector =
    ".blurb-items-wrapper .blurb-item .blurb-content .blurb-cta > a > span.text-capitalize.button-text";
  const newText = "Learn More";

  // Initial pass
  $(selector).text(newText);

  // Keep it updated if the Vue/JS app re-renders
  const root = document.querySelector(".blurb-items-wrapper") || document.body;

  const observer = new MutationObserver(() => {
    $(selector).each(function () {
      if (this.textContent !== newText) this.textContent = newText;
    });
  });

  observer.observe(root, { childList: true, subtree: true });
});



