/**
 * ADA/WAVE: clean up broken ARIA references introduced by Vue/OneTrust markup.
 *
 * Targets:
 *  1) Decorative arrows: .news-section .news-items .news-item .arrow
 *     - make decorative + remove labeling that triggers broken refs
 *
 *  2) OneTrust accordion buttons (example in screenshot):
 *     button[ot-accordion="true"][aria-controls][aria-labelledby]
 *     - KEEP aria-expanded
 *     - KEEP aria-controls / aria-labelledby ONLY if their referenced IDs exist
 *     - otherwise remove the broken attribute(s) (WAVE “Broken ARIA reference”)
 *
 * Notes:
 *  - This does NOT “nuke” accessibility for the accordion; it only removes ARIA that
 *    points to missing IDs. If the IDs exist, we keep them.
 *  - Re-runs after Vue/OT re-renders via MutationObserver.
 */
(function ($) {
  'use strict';

  const ARROW_SELECTOR = '.news-section .news-items .news-item .arrow';
  const OT_BUTTON_SELECTOR = 'button[ot-accordion="true"]';

  function idExists(id) {
    if (!id) return false;
    // Escape for CSS selector safety (handles IDs with special chars)
    const safe = (window.CSS && CSS.escape) ? CSS.escape(id) : id.replace(/([ #;?%&,.+*~\':"!^$[\]()=>|\/@])/g, '\\$1');
    return document.getElementById(id) || document.querySelector('#' + safe);
  }

  function sanitizeAriaLabelledby($el) {
    const val = ($el.attr('aria-labelledby') || '').trim();
    if (!val) return;

    const kept = val
      .split(/\s+/)
      .filter(Boolean)
      .filter((tok) => idExists(tok));

    if (kept.length) $el.attr('aria-labelledby', kept.join(' '));
    else $el.removeAttr('aria-labelledby');
  }

  function sanitizeAriaControls($el) {
    const id = ($el.attr('aria-controls') || '').trim();
    if (!id) return;

    if (!idExists(id)) $el.removeAttr('aria-controls');
  }

  function fixArrows(root) {
    const $root = root ? $(root) : $(document);

    $root.find(ARROW_SELECTOR).each(function () {
      const $el = $(this);

      // Remove labeling that can trigger broken-ref or name issues
      $el.removeAttr('aria-label aria-labelledby');
      $el.removeAttr('role');

      // Decorative
      $el.attr('aria-hidden', 'true');

      // Prevent focus if SVG/icon-like
      $el.attr('focusable', 'false').attr('tabindex', '-1');
    });
  }

  function fixOtAccordionButtons(root) {
    const $root = root ? $(root) : $(document);

    $root.find(OT_BUTTON_SELECTOR).each(function () {
      const $btn = $(this);

      // Only clean broken references; keep aria-expanded for state
      sanitizeAriaLabelledby($btn);
      sanitizeAriaControls($btn);

      // Optional hardening: if button has an explicit aria-label that is empty/whitespace, remove it
      const ariaLabel = $btn.attr('aria-label');
      if (typeof ariaLabel === 'string' && !ariaLabel.trim()) {
        $btn.removeAttr('aria-label');
      }
    });
  }

  function fixAll(root) {
    fixArrows(root);
    fixOtAccordionButtons(root);
  }

  function debounce(fn, wait) {
    let t;
    return function () {
      clearTimeout(t);
      t = setTimeout(fn, wait);
    };
  }

  $(function () {
    fixAll(document);

    const debounced = debounce(() => fixAll(document), 50);

    const obs = new MutationObserver((mutations) => {
      for (const m of mutations) {
        if (!m.addedNodes || !m.addedNodes.length) continue;

        for (const node of m.addedNodes) {
          if (node.nodeType !== 1) continue;

          // If any relevant nodes (or descendants) appear, re-run once (debounced)
          if (
            node.matches?.(ARROW_SELECTOR) ||
            node.matches?.(OT_BUTTON_SELECTOR) ||
            node.querySelector?.(ARROW_SELECTOR) ||
            node.querySelector?.(OT_BUTTON_SELECTOR)
          ) {
            debounced();
            return;
          }
        }
      }
    });

    obs.observe(document.body, { childList: true, subtree: true });
  });
})(jQuery);
		
		
		
/********* fixing issues with images on pipeline */
jQuery(function ($) {
  const ALT_TEXT = "display image to the right";

  function applyAlt() {
    $(".collab-img img.rights-img").each(function () {
      const $img = $(this);
      const alt = $img.attr("alt");

      // Only set if missing/empty to avoid overwriting meaningful alt text.
      if (alt === undefined || String(alt).trim() === "") {
        $img.attr("alt", ALT_TEXT);
      }
    });
  }

  // Initial pass
  applyAlt();

  // Catch SPA/Vue/async DOM updates
  const observer = new MutationObserver(function () {
    applyAlt();
  });

  observer.observe(document.body, { childList: true, subtree: true });
});




(function ($) {
  "use strict";

  /**
   * Copy the visible title text from:
   *   h3.wpgb-block-1 > a
   * into:
   *   a.wpgb-card-layer-link
   *
   * Runs on initial load + on WP Grid Builder refresh/AJAX changes.
   */

  function injectWpgbCardTitles(context) {
    var $root = context ? $(context) : $(document);

    $root.find("article.wpgb-card").each(function () {
      var $card = $(this);

      var $titleLink = $card.find("h3.wpgb-block-1 > a").first();
      var $layerLink = $card.find("a.wpgb-card-layer-link").first();

      if (!$titleLink.length || !$layerLink.length) return;

      // Use text() so we do not copy Wave extension injected icons/images.
      var titleText = $.trim($titleLink.text());
      if (!titleText) return;

      // Avoid unnecessary DOM writes.
      if ($.trim($layerLink.text()) !== titleText) {
        $layerLink.text(titleText);
      }

      // Optional hardening: ensure href matches the title link.
      var href = $titleLink.attr("href");
      if (href && $layerLink.attr("href") !== href) {
        $layerLink.attr("href", href);
      }
    });
  }

  // Initial pass (delayed slightly in case WPGBuilder renders after DOMReady).
  $(function () {
    injectWpgbCardTitles(document);
    setTimeout(function () {
      injectWpgbCardTitles(document);
    }, 250);
  });

  // Re-run after WP Grid Builder AJAX refreshes (common event names).
  $(document).on("wpgb:render wpgb:loaded wpgb:refresh", function (e, data) {
    // data could be a container; if not present, fallback to document.
    injectWpgbCardTitles(data && data.el ? data.el : document);
  });

  // Fallback: observe DOM mutations within WPGB container(s).
  // This covers cases where WPGB does not emit events in your setup.
  $(function () {
    var $containers = $(".wpgb-grid, .wpgb-grid-wrapper, .wpgb-facet");
    if (!$containers.length || !window.MutationObserver) return;

    var obs = new MutationObserver(function () {
      injectWpgbCardTitles(document);
    });

    $containers.each(function () {
      obs.observe(this, { childList: true, subtree: true });
    });
  });
})(jQuery);

body.script:
/**
 * Consolidated solution:
 * 1) Force full reloads for same-origin internal links (stabilize CSS/JS injections).
 * 2) Special-case /careers/#open-positions by rewriting to /careers/?scrollto=open-positions
 *    to avoid Vue hash watchers and scroll snap-back.
 * 3) On /careers/ with ?scrollto=open-positions, reliably scroll after load/hydration
 *    (retries and supports non-window scroll containers).
 * 4) Strip any re-added #open-positions repeatedly for a short window.
 */

(function () {
  /************** CONFIG **************/
  const FORCE_ALL_INTERNAL = true;
  const ONLY_PATH_PREFIXES = []; // optional allowlist when FORCE_ALL_INTERNAL=false
  const EXCLUDE_PATH_PREFIXES = ["/wp-admin", "/wp-login.php"];

  const CAREERS_PATH_PREFIX = "/careers";
  const CAREERS_ID = "open-positions";
  const SCROLL_PARAM = "scrollto";

  const HEADER_OFFSET_PX = 0; // set if fixed header

  const FIND_TARGET_MAX_WAIT_MS = 12000;
  const SCROLL_RETRY_WINDOW_MS = 3000;
  const SCROLL_RETRY_EVERY_MS = 100;
  const SUCCESS_TOL_PX = 25;

  const HASH_STRIP_WINDOW_MS = 10000; // keep stripping #open-positions if Vue re-adds it
  const HASH_STRIP_EVERY_MS = 200;

  /************** HELPERS **************/
  function isModifiedClick(e) {
    return (
      e.defaultPrevented ||
      e.button !== 0 ||
      e.metaKey ||
      e.ctrlKey ||
      e.shiftKey ||
      e.altKey
    );
  }

  function isSameOrigin(url) {
    return url && url.origin === location.origin;
  }

  function normalizeCareersHashToQuery(url) {
    // /careers/#open-positions => /careers/?scrollto=open-positions
    if (!isSameOrigin(url)) return url;
    if (!url.pathname.startsWith(CAREERS_PATH_PREFIX)) return url;

    const hashId = (url.hash || "").replace(/^#/, "");
    if (hashId === CAREERS_ID) {
      url.hash = "";
      url.searchParams.set(SCROLL_PARAM, CAREERS_ID);
    }
    return url;
  }

  function shouldForceHardNav(url) {
    if (!isSameOrigin(url)) return false;

    // exclude paths
    for (const p of EXCLUDE_PATH_PREFIXES) {
      if (url.pathname.startsWith(p)) return false;
    }

    // same-page anchor jumps should be left alone
    const samePathQuery =
      url.pathname === location.pathname && url.search === location.search;
    if (samePathQuery && url.hash) return false;

    if (!FORCE_ALL_INTERNAL) {
      if (ONLY_PATH_PREFIXES.length) {
        let ok = false;
        for (const p of ONLY_PATH_PREFIXES) if (url.pathname.startsWith(p)) ok = true;
        if (!ok) return false;
      }
    }

    return true;
  }

  function findScrollableParent(el) {
    let node = el && el.parentElement;
    while (node && node !== document.body && node !== document.documentElement) {
      const cs = window.getComputedStyle(node);
      const oy = cs.overflowY;
      const canScroll =
        (oy === "auto" || oy === "scroll" || oy === "overlay") &&
        node.scrollHeight > node.clientHeight + 1;
      if (canScroll) return node;
      node = node.parentElement;
    }
    return null;
  }

  function scrollToEl(el) {
    if (!el) return false;
    const scroller = findScrollableParent(el);
    const rect = el.getBoundingClientRect();

    if (scroller) {
      const srect = scroller.getBoundingClientRect();
      const delta = rect.top - srect.top;
      const y = scroller.scrollTop + delta - HEADER_OFFSET_PX;
      scroller.scrollTo({ top: y, behavior: "auto" });
      return true;
    }

    const y = rect.top + window.scrollY - HEADER_OFFSET_PX;
    window.scrollTo({ top: y, behavior: "auto" });
    return true;
  }

  function isAtEl(el) {
    if (!el) return false;
    const scroller = findScrollableParent(el);
    const rect = el.getBoundingClientRect();

    if (scroller) {
      const srect = scroller.getBoundingClientRect();
      const dist = Math.abs((rect.top - srect.top) - HEADER_OFFSET_PX);
      return dist <= SUCCESS_TOL_PX;
    }

    const dist = Math.abs(rect.top - HEADER_OFFSET_PX);
    return dist <= SUCCESS_TOL_PX;
  }

  function removeParam(param) {
    const u = new URL(location.href);
    if (!u.searchParams.has(param)) return;
    u.searchParams.delete(param);
    const qs = u.searchParams.toString();
    history.replaceState(history.state, document.title, u.pathname + (qs ? "?" + qs : ""));
  }

  function stripCareersHashOnce() {
    if (!location.pathname.startsWith(CAREERS_PATH_PREFIX)) return;
    const hashId = (location.hash || "").replace(/^#/, "");
    if (hashId !== CAREERS_ID) return;

    // Remove hash (keep query)
    history.replaceState(history.state, document.title, location.pathname + location.search);
  }

  /************** 1) CLICK INTERCEPTOR **************/
  document.addEventListener(
    "click",
    function (e) {
      if (isModifiedClick(e)) return;

      const a = e.target && e.target.closest ? e.target.closest("a[href]") : null;
      if (!a) return;

      const href = a.getAttribute("href") || "";
      if (!href) return;

      if (a.hasAttribute("download")) return;
      if (/^(mailto:|tel:|javascript:)/i.test(href)) return;

      // pure same-page anchor like "#foo"
      if (href.trim().startsWith("#")) return;

      let url;
      try {
        url = new URL(href, location.href);
      } catch (_) {
        return;
      }

      // rewrite careers hash => query
      url = normalizeCareersHashToQuery(url);

      if (!shouldForceHardNav(url)) return;

      e.preventDefault();
      e.stopPropagation();
      if (typeof e.stopImmediatePropagation === "function") e.stopImmediatePropagation();

      const target = (a.getAttribute("target") || "_self").toLowerCase();
      if (target === "_blank") {
        const w = window.open(url.href, "_blank", "noopener,noreferrer");
        if (!w) window.location.assign(url.href);
        return;
      }

      window.location.assign(url.href);
    },
    true
  );

  /************** 2) CAREERS ?scrollto=... SCROLLER **************/
  function runCareersScroll() {
    if (!location.pathname.startsWith(CAREERS_PATH_PREFIX)) return;

    // If user somehow lands with #open-positions, convert it immediately to query
    const hid = (location.hash || "").replace(/^#/, "");
    if (hid === CAREERS_ID) {
      const u = new URL(location.href);
      u.hash = "";
      u.searchParams.set(SCROLL_PARAM, CAREERS_ID);
      history.replaceState(history.state, document.title, u.pathname + "?" + u.searchParams.toString());
    }

    const sp = new URLSearchParams(location.search);
    const target = sp.get(SCROLL_PARAM);
    if (target !== CAREERS_ID) return;

    // prevent browser restoring old scroll while we fight SPA behavior
    const prev = history.scrollRestoration;
    try { history.scrollRestoration = "manual"; } catch (_) {}

    const t0 = Date.now();
    let el = null;

    const finder = setInterval(() => {
      const elapsed = Date.now() - t0;
      el = document.getElementById(CAREERS_ID);

      if (el) {
        clearInterval(finder);

        // Scroll attempts after layout settles
        const startRetry = Date.now();
        const retry = setInterval(() => {
          if (!document.documentElement.contains(el)) return;

          scrollToEl(el);

          if (isAtEl(el)) {
            clearInterval(retry);
            removeParam(SCROLL_PARAM);
            try { history.scrollRestoration = prev || "auto"; } catch (_) {}
            return;
          }

          if (Date.now() - startRetry > SCROLL_RETRY_WINDOW_MS) {
            clearInterval(retry);
            removeParam(SCROLL_PARAM);
            try { history.scrollRestoration = prev || "auto"; } catch (_) {}
          }
        }, SCROLL_RETRY_EVERY_MS);

        // do first attempt on next frames (beats "scroll to top" on mount)
        requestAnimationFrame(() => requestAnimationFrame(() => scrollToEl(el)));
      }

      if (elapsed > FIND_TARGET_MAX_WAIT_MS) {
        clearInterval(finder);
        removeParam(SCROLL_PARAM);
        try { history.scrollRestoration = prev || "auto"; } catch (_) {}
      }
    }, 50);
  }

  /************** 3) STRIP RE-ADDED #open-positions FOR A WINDOW **************/
  function enforceHashStripWindow() {
    if (!location.pathname.startsWith(CAREERS_PATH_PREFIX)) return;

    const t0 = Date.now();
    const iv = setInterval(() => {
      if (Date.now() - t0 > HASH_STRIP_WINDOW_MS) {
        clearInterval(iv);
        return;
      }
      stripCareersHashOnce();
    }, HASH_STRIP_EVERY_MS);
  }

  // Run now + after load (covers late hydration)
  runCareersScroll();
  enforceHashStripWindow();
  window.addEventListener("load", () => {
    runCareersScroll();
    enforceHashStripWindow();
  }, { once: true });

  // If hash changes later, strip it again (cheap)
  window.addEventListener("hashchange", stripCareersHashOnce);
})();
	
	
	
	
	
	
	
	
	
	
	/**
 * Hide any  elements with href="#hide"
 * - Runs on DOM ready
 * - Also observes future DOM changes (useful for SPA/Vue/WP blocks)
 */
(function () {
  function hideHashHideLinks(root) {
    const scope = root && root.nodeType === 1 ? root : document;
    scope.querySelectorAll('a[href="#hide"]').forEach((a) => {
      a.style.setProperty('display', 'none', 'important');
      a.setAttribute('aria-hidden', 'true');
      a.setAttribute('tabindex', '-1');
    });
  }

  // Initial pass
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => hideHashHideLinks(document));
  } else {
    hideHashHideLinks(document);
  }

  // Watch for dynamically-inserted links
  const obs = new MutationObserver((mutations) => {
    for (const m of mutations) {
      for (const node of m.addedNodes) {
        hideHashHideLinks(node);
      }
    }
  });

  obs.observe(document.documentElement, { childList: true, subtree: true });
})();

(function ($) {
  var MOBILE_BREAKPOINT = 1024;
  var panelCounter = 0;
  var initTimer = null;

  function isMobile() {
    return window.matchMedia("(max-width: " + MOBILE_BREAKPOINT + "px)").matches;
  }

  function setExpanded($parent, expanded, pinned) {
    expanded = !!expanded;
    pinned = !!pinned && expanded;

    $parent.toggleClass("psudo-open", expanded);
    $parent.toggleClass("psudo-pinned", pinned);

    $parent.children("a").first().attr("aria-expanded", expanded ? "true" : "false");
    $parent.children(".psudo-toggle").attr("aria-expanded", expanded ? "true" : "false");
    $parent.children(".psudo-panel").attr("aria-hidden", expanded ? "false" : "true");

    if (isMobile()) {
      syncSubmenuHeight($parent);
    }
  }

  function closeSiblings($parent) {
    $parent
      .siblings("li.psudo-submenu.psudo-open")
      .each(function () {
        setExpanded($(this), false, false);
      });
  }

  function openParent($parent, pinned) {
    closeSiblings($parent);
    setExpanded($parent, true, pinned);
  }

  function toggleParent($parent) {
    if ($parent.hasClass("psudo-open") && $parent.hasClass("psudo-pinned")) {
      setExpanded($parent, false, false);
      return;
    }
    openParent($parent, true);
  }

  function syncSubmenuHeight($item) {
    if (!isMobile()) {
      return;
    }

    var $submenuWrapper = $item.closest("ul").parent("div");

    if (!$submenuWrapper.length) {
      return;
    }

    window.requestAnimationFrame(function () {
      var newHeight = $submenuWrapper.children("ul").outerHeight(true);
      if (newHeight) {
        $submenuWrapper.css("height", newHeight + "px");
      }
    });
  }

  function refreshOpenHeights() {
    if (!isMobile()) {
      return;
    }

    $("li.psudo-submenu.psudo-open").each(function () {
      syncSubmenuHeight($(this));
    });
  }

  function buildPseudoPanels(context) {
    $(context)
      .find("li.psudo-submenu")
      .each(function () {
        var $parent = $(this);

        if ($parent.data("psudoBuilt")) {
          return;
        }

        var $children = $();
        var $next = $parent.next("li");

        while ($next.length && $next.hasClass("psudo-subitem")) {
          $children = $children.add($next);
          $next = $next.next("li");
        }

        $parent.data("psudoBuilt", true);

        if (!$children.length) {
          return;
        }

        panelCounter += 1;
        var panelId = "psudo-panel-" + panelCounter;

        var $toggle = $parent.children(".psudo-toggle");
        if (!$toggle.length) {
          $toggle = $(
            '' +
              '+' +
            ""
          );
          $parent.append($toggle);
        }

        var $panel = $('').attr("id", panelId);

        $children.appendTo($panel);

        $parent
          .addClass("psudo-has-children psudo-enhanced")
          .append($panel);

        $parent
          .children("a")
          .first()
          .attr({
            "aria-haspopup": "true",
            "aria-expanded": "false",
            "role": "button"
          });

        $toggle.attr({
          "aria-controls": panelId,
          "aria-expanded": "false"
        });
      });
  }

  function queueInit() {
    clearTimeout(initTimer);
    initTimer = setTimeout(function () {
      buildPseudoPanels(document.body);
      refreshOpenHeights();
    }, 60);
  }

  $(document)

    .on("mouseenter", "li.psudo-submenu.psudo-has-children", function () {
      if (isMobile()) {
        return;
      }
      openParent($(this), false);
    })

    .on("mouseleave", "li.psudo-submenu.psudo-has-children", function () {
      if (isMobile()) {
        return;
      }

      var $parent = $(this);
      if ($parent.hasClass("psudo-pinned")) {
        return;
      }

      setExpanded($parent, false, false);
    })

    .on("focusin", "li.psudo-submenu.psudo-has-children", function () {
      if (isMobile()) {
        return;
      }
      openParent($(this), false);
    })

    .on("click", "li.psudo-submenu.psudo-has-children > a, li.psudo-submenu.psudo-has-children > .psudo-toggle", function (e) {
      e.preventDefault();
      e.stopPropagation();

      var $parent = $(this).closest("li.psudo-submenu");
      toggleParent($parent);
    });

  $(document).on("click", function (e) {
    if ($(e.target).closest("li.psudo-submenu.psudo-has-children").length) {
      return;
    }

    $("li.psudo-submenu.psudo-pinned").each(function () {
      setExpanded($(this), false, false);
    });
  });

  $(document).on("keydown", function (e) {
    if (e.key !== "Escape") {
      return;
    }

    $("li.psudo-submenu.psudo-open").each(function () {
      setExpanded($(this), false, false);
    });
  });

  $(window).on("resize", function () {
    refreshOpenHeights();
  });

  $(function () {
    buildPseudoPanels(document.body);
    refreshOpenHeights();

    if (window.MutationObserver) {
      var observer = new MutationObserver(function (mutations) {
        var shouldRebuild = false;

        for (var i = 0; i < mutations.length; i++) {
          var mutation = mutations[i];

          if (!mutation.addedNodes || !mutation.addedNodes.length) {
            continue;
          }

          for (var j = 0; j < mutation.addedNodes.length; j++) {
            var node = mutation.addedNodes[j];

            if (node.nodeType !== 1) {
              continue;
            }

            if (
              $(node).is("li.psudo-submenu, li.psudo-subitem") ||
              $(node).find("li.psudo-submenu, li.psudo-subitem").length
            ) {
              shouldRebuild = true;
              break;
            }
          }

          if (shouldRebuild) {
            break;
          }
        }

        if (shouldRebuild) {
          queueInit();
        }
      });

      observer.observe(document.body, {
        childList: true,
        subtree: true
      });
    }
  });
})(jQuery);

