function InitAutoOpenModal(){
	var hash = window.location.hash,
		modalBtn = jQuery('a.modal-btn[href^="'+hash+'"]');
	
	if (modalBtn.length){
		modalBtn.trigger('click');
		
		modalBtn.click(function(){
