function InitSubMenuOnHover(){
	
	jQuery('.desktop-nav .desktop-nav-wrapper .nav-lists li.nav-item-wrapper').each(function () {
        jQuery(this).mouseenter(function() {
			jQuery(this).find('.parent button').trigger('click');
